def _aicasgc_quantnative_bind_gateup_args(*items):
    mapping = {}
    try:
        max_weights = 0
    except Exception:
        max_weights = 0
    mask_raw = "0-27"
    mask = None
    if mask_raw and mask_raw not in {"all", "*"}:
        try:
            mask = set()
            for item in mask_raw.split(","):
                part = item.strip()
                if not part:
                    continue
                if "-" in part:
                    lo_s, hi_s = part.split("-", 1)
                    lo = int(lo_s.strip())
                    hi = int(hi_s.strip())
                    if hi < lo:
                        lo, hi = hi, lo
                    mask.update(range(lo, hi + 1))
                else:
                    mask.add(int(part))
        except Exception:
            mask = None
    bound = 0
    for idx in range(0, len(items), 3):
        layer_idx = idx // 3
        if mask is not None and layer_idx not in mask:
            continue
        if max_weights > 0 and bound >= max_weights:
            break
        try:
            weight = items[idx]
            qweight = items[idx + 1]
            scales = items[idx + 2]
        except Exception:
            continue
        if isinstance(weight, torch.Tensor) and isinstance(qweight, torch.Tensor) and isinstance(scales, torch.Tensor):
            mapping[int(weight.data_ptr())] = (qweight, scales)
            bound += 1
    globals()["_AICASGC_QUANTNATIVE_W8A16_GATEUP"] = mapping


class _AICASGCQuantNativeW8A16GateUpRunner:
    def __init__(self, original_runner):
        self._original_runner = original_runner
        self._failed = False
        self._block_n = max(1, int("16"))
        self._block_k = max(16, int("128"))

    def _fallback(self, *args, **kwargs):
        _aicasgc_row_w8a16_stat("fallbacks")
        return self._original_runner.run(*args, **kwargs)

    def _fallback_reason(self, reason, *args, **kwargs):
        if os.environ.get("AICASGC_DEBUG_PPU", "0") != "0":
            key = f"_AICASGC_ROW_W8A16_FALLBACK_PRINTS_{reason}"
            count = int(globals().get(key, 0))
            limit = 8 if reason == "missing_pack" else 32
            if count < limit:
                globals()[key] = count + 1
                print(f"[AICASGC-rowtriton] fallback reason={reason}")
        return self._fallback(*args, **kwargs)

    @staticmethod
    def _is_gate_up_weight(tensor):
        return (
            isinstance(tensor, torch.Tensor)
            and tensor.ndim == 2
            and int(tensor.shape[0]) == 12288
            and int(tensor.shape[1]) == 2048
        )

    @staticmethod
    def _is_hidden_vec(tensor):
        return isinstance(tensor, torch.Tensor) and int(tensor.numel()) == 2048

    @staticmethod
    def _is_sumsq(tensor):
        return isinstance(tensor, torch.Tensor) and int(tensor.numel()) == 1

    def _parse_run_args(self, args):
        if (
            len(args) >= 5
            and self._is_hidden_vec(args[0])
            and self._is_gate_up_weight(args[1])
            and isinstance(args[2], torch.Tensor)
            and int(args[3]) == 12288
            and int(args[4]) == 2048
        ):
            return "plain", args[0], None, None, args[1], args[2]
        if (
            len(args) >= 7
            and self._is_hidden_vec(args[0])
            and self._is_sumsq(args[1])
            and self._is_hidden_vec(args[2])
            and self._is_gate_up_weight(args[3])
            and isinstance(args[4], torch.Tensor)
            and int(args[5]) == 12288
            and int(args[6]) == 2048
        ):
            return "norm", args[0], args[1], args[2], args[3], args[4]
        return None

    def run(self, *args, **kwargs):
        _aicasgc_row_w8a16_stat("calls")
        parsed = self._parse_run_args(args)
        if parsed is None:
            _aicasgc_row_w8a16_stat("parse_miss")
            return self._fallback_reason("parse_miss", *args, **kwargs)
        if self._failed:
            return self._fallback_reason("failed", *args, **kwargs)
        mode, hidden_in, sum_squares, norm_weight, gate_up_weight, out = parsed
        packed = globals().get("_AICASGC_QUANTNATIVE_W8A16_GATEUP", {}).get(int(gate_up_weight.data_ptr()))
        if packed is None:
            _aicasgc_row_w8a16_stat("missing_pack")
            return self._fallback_reason("missing_pack", *args, **kwargs)
        try:
            if mode == "norm":
                if not isinstance(sum_squares, torch.Tensor) or not isinstance(norm_weight, torch.Tensor):
                    return self._fallback_reason("bad_norm_args", *args, **kwargs)
                hidden = hidden_in
            else:
                hidden = hidden_in
            qweight, scales = packed
            if (
                not isinstance(qweight, torch.Tensor)
                or not isinstance(scales, torch.Tensor)
                or qweight.dtype != torch.int8
                or scales.dtype != torch.float16
                or tuple(qweight.shape) != (12288, 2048)
                or int(scales.numel()) != 12288
            ):
                if os.environ.get("AICASGC_DEBUG_PPU", "0") != "0":
                    q_desc = (
                        f"dtype={getattr(qweight, 'dtype', None)}, "
                        f"shape={tuple(qweight.shape) if isinstance(qweight, torch.Tensor) else None}"
                    )
                    s_desc = (
                        f"dtype={getattr(scales, 'dtype', None)}, "
                        f"shape={tuple(scales.shape) if isinstance(scales, torch.Tensor) else None}, "
                        f"numel={int(scales.numel()) if isinstance(scales, torch.Tensor) else None}"
                    )
                    print(f"[AICASGC-rowtriton] packed layout mismatch: qweight({q_desc}), scales({s_desc})")
                return self._fallback_reason("layout_mismatch", *args, **kwargs)
            launcher = globals().get("_aicas_triton_row_w8a16_gateup_norm" if mode == "norm" else "_aicas_triton_row_w8a16_gateup")
            if not callable(launcher):
                return self._fallback_reason("launcher_missing", *args, **kwargs)
            if os.environ.get("AICASGC_DEBUG_PPU", "0") != "0" and int(globals().get("_AICASGC_ROW_W8A16_DEBUG_LAUNCHES", 0)) < 1:
                globals()["_AICASGC_ROW_W8A16_DEBUG_LAUNCHES"] = int(globals().get("_AICASGC_ROW_W8A16_DEBUG_LAUNCHES", 0)) + 1
                print(
                    "[AICASGC-rowtriton] launching row kernel "
                    f"mode={mode}, hidden_dtype={hidden.dtype}, hidden_shape={tuple(hidden.shape)}, "
                    f"q_dtype={qweight.dtype}, q_shape={tuple(qweight.shape)}, "
                    f"s_dtype={scales.dtype}, s_shape={tuple(scales.shape)}, "
                    f"out_dtype={out.dtype}, out_shape={tuple(out.shape)}"
                )
            if mode == "norm":
                launched = launcher(
                    hidden,
                    sum_squares,
                    norm_weight,
                    qweight,
                    scales,
                    out,
                    block_n=int(self._block_n),
                    block_k=int(self._block_k),
                )
            else:
                launched = launcher(
                    hidden,
                    qweight,
                    scales,
                    out,
                    block_n=int(self._block_n),
                    block_k=int(self._block_k),
                )
            if not launched:
                return self._fallback_reason("launcher_rejected", *args, **kwargs)
            _aicasgc_row_w8a16_stat("hits")
            return None
        except Exception:
            _aicasgc_row_w8a16_stat("exceptions")
            if os.environ.get("AICASGC_DEBUG_PPU", "0") != "0":
                import traceback
                print("[AICASGC-rowtriton] w8a16 gate/up run failed:")
                try:
                    print(
                        "[AICASGC-rowtriton] context "
                        f"mode={mode}, "
                        f"hidden_dtype={getattr(hidden, 'dtype', None)}, "
                        f"hidden_shape={tuple(hidden.shape) if isinstance(hidden, torch.Tensor) else None}, "
                        f"q_dtype={getattr(qweight, 'dtype', None)}, "
                        f"q_shape={tuple(qweight.shape) if isinstance(qweight, torch.Tensor) else None}, "
                        f"s_dtype={getattr(scales, 'dtype', None)}, "
                        f"s_shape={tuple(scales.shape) if isinstance(scales, torch.Tensor) else None}, "
                        f"out_dtype={getattr(out, 'dtype', None)}, "
                        f"out_shape={tuple(out.shape) if isinstance(out, torch.Tensor) else None}, "
                        f"block_n={self._block_n}, block_k={self._block_k}"
                    )
                except Exception:
                    pass
                traceback.print_exc()
            self._failed = True
            return self._fallback_reason("exception", *args, **kwargs)


def _aicasgc_patch_quantnative_w8a16_gateup():
    requested = os.environ.get("AICASGC_QUANTNATIVE_W8A16_GATEUP_RUNNERS", "plain").strip().lower() or "plain"
    runner_names = ("triton_red_fused_mm_11", "triton_red_fused_mm_18")
    if requested in {"plain", "mm11"}:
        runner_names = ("triton_red_fused_mm_11",)
    elif requested in {"norm", "mm18"}:
        runner_names = ("triton_red_fused_mm_18",)
    elif requested not in {"all", "*"}:
        allowed = {item.strip() for item in requested.split(",") if item.strip()}
        runner_names = tuple(name for name in runner_names if name in allowed)
    for runner_name in runner_names:
        runner = globals().get(runner_name)
        if runner is not None and callable(getattr(runner, "run", None)):
            globals()[runner_name] = _AICASGCQuantNativeW8A16GateUpRunner(runner)



